const item = $input.item.json;

// The agent has to echo back the exact question_id for every question. It only
// has to garble one UUID to break the insert on session_answer.question_id, and
// across a whole project that is hundreds of reproductions. Validate against the
// list we actually handed it - the same guard L2 applies to its citations.
// Dropping is deliberate rather than re-matching by position: the schema asks
// for one entry per question in order, but a single omission would shift every
// later answer onto the wrong question.
const offered = $('Aggregate Questions').first().json.questions || [];
const validIds = new Set(offered.map(q => String(q.id)));
const qid = String(item.question_id || '');
if (!validIds.has(qid)) { return null; }

const clips = item.clips || [];
const norm = (s) => (s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const words = $('Fetch Session').item.json.transcript_object || [];
const verifiedClips = [];

if (Array.isArray(words) && words.length > 0) {
  const stats = {};
  for (const w of words) {
    const sp = String(w.speaker);
    if (!stats[sp]) stats[sp] = { words: 0, q: 0, first: Infinity };
    stats[sp].words++;
    const pw = w.punctuated_word || '';
    if (pw.charAt(pw.length - 1) === '?') stats[sp].q++;
    const st = Number(w.start);
    if (!isNaN(st) && st < stats[sp].first) stats[sp].first = st;
  }
  const speakers = Object.keys(stats);
  let participant = null;

  if (speakers.length > 1) {
    const anyQ = speakers.some(s => stats[s].q > 0);
    const byQRate = speakers.slice().sort((a, b) => (stats[b].q / stats[b].words) - (stats[a].q / stats[a].words));
    const byFirst = speakers.slice().sort((a, b) => stats[a].first - stats[b].first);
    const interviewerQ = anyQ ? byQRate[0] : null;
    const interviewerFirst = byFirst[0];
    let interviewer = null;
    if (interviewerQ !== null && interviewerQ === interviewerFirst) interviewer = interviewerQ;
    else if (interviewerQ === null) interviewer = interviewerFirst;
    if (interviewer !== null) {
      const rest = speakers.filter(s => s !== interviewer);
      if (rest.length > 0) {
        rest.sort((a, b) => stats[b].words - stats[a].words);
        participant = rest[0];
      }
    }
  }

  const tokens = words.map(w => norm(w.word));
  const firstIndex = new Map();
  for (let i = 0; i < tokens.length; i++) {
    if (!firstIndex.has(tokens[i])) firstIndex.set(tokens[i], []);
    firstIndex.get(tokens[i]).push(i);
  }

  for (const clip of clips) {
    const q = norm(clip.quote).split(' ').filter(t => t.length > 0);
    if (q.length === 0) continue;
    const starts = firstIndex.get(q[0]) || [];
    let found = -1;
    for (const s of starts) {
      if (s + q.length > tokens.length) break;
      let ok = true;
      for (let j = 1; j < q.length; j++) { if (tokens[s + j] !== q[j]) { ok = false; break; } }
      if (ok) { found = s; break; }
    }
    if (found === -1) continue;
    const end = found + q.length - 1;
    const spanSpeakers = new Set();
    for (let k = found; k <= end; k++) spanSpeakers.add(String(words[k].speaker));
    if (spanSpeakers.size > 1) continue;
    if (participant !== null && String(words[found].speaker) !== participant) continue;
    verifiedClips.push({ quote: clip.quote, start_time: words[found].start, end_time: words[end].end });
  }
} else {
  const t = norm($('Fetch Session').item.json.transcript || '');
  for (const clip of clips) {
    const nq = norm(clip.quote);
    if (nq && t.indexOf(nq) !== -1) verifiedClips.push({ quote: clip.quote, start_time: null, end_time: null });
  }
}

const wasAsked = Boolean(item.was_asked) && verifiedClips.length > 0;
return { json: { question_id: qid, was_asked: wasAsked, summary: wasAsked ? item.summary : '', tags: wasAsked ? (item.tags || []) : [], clips: verifiedClips } };

