  }
}

if (verifiedClips.length === 0) { return null; }
return { json: { question_text: item.question_text, summary: item.summary, clips: verifiedClips } };

// The agent must echo back the exact question_id for every question - hundreds
// of UUID reproductions per project - and a single garbled one breaks the
// insert on session_answer.question_id. Validation alone would cost that
// answer, and a dropped answer looks exactly like a question the participant
// never addressed, which is the silent loss this pipeline exists to avoid.
//
// Recover only the unambiguous case: if exactly one returned id is invalid and
// exactly one offered id is unclaimed, the malformed entry can only belong to
// that question. With two or more, assignment would depend on the agent having
// kept its ordering, and a misattributed answer is worse than a missing one.
const raw = $input.first().json;
const out = raw.output || raw;
const answers = (out.answers || []).map(a => Object.assign({}, a));
const offered = $('Aggregate Questions').first().json.questions || [];
const offeredIds = offered.map(q => String(q.id));
const validIds = new Set(offeredIds);

const seen = new Map();
for (const a of answers) {
  const id = String(a.question_id || '');
  if (!validIds.has(id)) { continue; }
  seen.set(id, (seen.get(id) || 0) + 1);
}
let duplicates = 0;
for (const n of seen.values()) { if (n > 1) { duplicates += n - 1; } }

const unclaimed = offeredIds.filter(id => !seen.has(id));
const bad = answers.filter(a => !validIds.has(String(a.question_id || '')));

let repaired = 0;
if (bad.length === 1 && unclaimed.length === 1) {
  bad[0].question_id = unclaimed[0];
  repaired = 1;
}

const kept = answers.filter(a => validIds.has(String(a.question_id || '')));
const dropped = answers.length - kept.length;

return [{ json: {
  output: { answers: kept, emergent_questions: out.emergent_questions || [] },
  repair: { offered: offeredIds.length, returned: answers.length, repaired: repaired, dropped: dropped, duplicate_ids: duplicates }
} }];
